INSERT INTO categorias (categoria_id, nome, descricao, icone, ordem) VALUES ('elegibilidade', 'Elegibilidade', 'Quem pode se inscrever no PROUNI e critérios de renda.', 'bi-person-check', 1);
INSERT INTO categorias (categoria_id, nome, descricao, icone, ordem) VALUES ('como-se-inscrever', 'Como se Inscrever', 'Passo a passo da inscrição no sistema oficial.', 'bi-clipboard-check', 2);
INSERT INTO categorias (categoria_id, nome, descricao, icone, ordem) VALUES ('documentacao', 'Documentação', 'Documentos que você precisa reunir para comprovar tudo.', 'bi-file-earmark-text', 3);
INSERT INTO categorias (categoria_id, nome, descricao, icone, ordem) VALUES ('prazos', 'Prazos', 'Datas e cronograma que você precisa acompanhar.', 'bi-calendar-check', 4);
INSERT INTO categorias (categoria_id, nome, descricao, icone, ordem) VALUES ('renovacao-de-bolsa', 'Renovação de Bolsa', 'Como manter sua bolsa ao longo do curso.', 'bi-arrow-repeat', 5);
INSERT INTO categorias (categoria_id, nome, descricao, icone, ordem) VALUES ('perda-da-bolsa', 'Perda da Bolsa', 'Situações que podem levar à suspensão ou ao encerramento definitivo da bolsa.', 'bi-exclamation-triangle', 6);
INSERT INTO categorias (categoria_id, nome, descricao, icone, ordem) VALUES ('direitos-e-beneficios', 'Direitos e Benefícios do Bolsista', 'Vantagens, garantias e oportunidades extras que a lei assegura a quem tem bolsa PROUNI.', 'bi-award', 7);
INSERT INTO categorias (categoria_id, nome, descricao, icone, ordem) VALUES ('procedimentos-e-contato-na-feevale', 'Procedimentos e Contato na Feevale', 'Entrega de documentos, transferências, comprovantes e contato com o NAE na Feevale.', 'bi-file-earmark-check', 8);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('eleg-1', 'elegibilidade', NULL, 'Quem pode se inscrever no PROUNI?', 'Podem se inscrever brasileiros(as) sem diploma de curso superior que tenham participado de uma das duas edições mais recentes do ENEM (não valendo participação como ''treineiro''), com média mínima de 450 pontos nas provas objetivas e nota acima de zero na redação. Também é necessário se enquadrar em um dos critérios de renda.', 1);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-1', 'a', 'Atenda aos critérios de ENEM, renda e escolaridade.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-1', 'b', 'Tenha diploma de curso superior.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-1', 'c', 'Não tenha feito o ENEM.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-1', 'd', 'Faça a inscrição diretamente na Feevale.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('eleg-2', 'elegibilidade', NULL, 'Qual é o limite de renda familiar para conseguir uma bolsa?', 'Na Feevale, são ofertadas apenas bolsas integrais, que exigem renda familiar bruta mensal de até 1,5 salário mínimo por pessoa. O PROUNI também prevê bolsas parciais (50%), com limite de até 3 salários mínimos por pessoa, mas esse tipo de bolsa não é ofertado pela Feevale.', 2);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-2', 'a', 'Até 3 salários mínimos por pessoa em qualquer bolsa.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-2', 'b', 'Até 1,5 salário mínimo por pessoa para bolsa integral.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-2', 'c', 'Apenas renda familiar acima de 5 salários mínimos.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-2', 'd', 'Não existe limite de renda.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('eleg-3', 'elegibilidade', NULL, 'É preciso ter estudado em escola pública para participar?', 'Não necessariamente. Você pode se inscrever em qualquer uma destas situações de ensino médio: 1) integralmente em escola pública; 2) integralmente em escola privada, como bolsista integral; 3) parte em pública e parte em privada, como bolsista integral; 4) parte em pública e parte em privada, como bolsista parcial ou sem bolsa; 5) integralmente em escola privada, como bolsista parcial ou sem bolsa. O que muda entre elas não é o direito de se inscrever, e sim a prioridade na ordem de classificação: quem se enquadra nas situações 1 e 3 tem prioridade mais alta (equivalente à de professor da rede pública em cursos de licenciatura/pedagogia), seguido de quem se enquadra na situação 2, depois na 4, e por último na 5.', 3);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-3', 'a', 'Sim, somente escola pública é aceita.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-3', 'b', 'Sim, apenas escola privada com bolsa integral.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-3', 'c', 'Não necessariamente; há outras situações aceitas.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-3', 'd', 'Não é preciso comprovar o ensino médio.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('eleg-4', 'elegibilidade', NULL, 'Já concluí uma faculdade antes. Posso participar mesmo assim?', 'Não. O PROUNI é destinado a quem ainda não possui diploma de curso superior. Quem já concluiu uma graduação, mesmo que em outra área, não pode concorrer a uma bolsa.', 4);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-4', 'a', 'Não, quem já tem diploma não pode concorrer.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-4', 'b', 'Sim, qualquer diploma permite nova bolsa.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-4', 'c', 'Sim, mas somente na mesma área.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-4', 'd', 'Sim, desde que não tenha usado o ENEM.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('eleg-5', 'elegibilidade', NULL, 'Existe alguma exceção à regra de escola pública ou de renda?', 'Sim. Professores da rede pública em efetivo exercício do magistério da educação básica. Neste caso, apenas para bolsas em cursos de licenciatura e pedagogia, sem necessidade de atender ao limite de renda.', 5);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-5', 'a', 'Não há exceções para renda ou escolaridade.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-5', 'b', 'Somente estudantes de escola pública têm exceção.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-5', 'c', 'A exceção vale para qualquer curso sem critérios.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-5', 'd', 'Professores da rede pública podem ter exceção para cursos de licenciatura e pedagogia.', true);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('eleg-6', 'elegibilidade', NULL, 'Como calculo se minha renda familiar está dentro do limite do PROUNI?', 'Some a renda bruta de todos os integrantes do grupo familiar e divida pelo número de integrantes. Esse é o valor da renda per capita. Para a bolsa integral, esse valor não pode ultrapassar 1,5 salário mínimo vigente. Por exemplo: uma família com renda bruta total de R$ 2.500,00 e 4 integrantes tem renda per capita de R$ 625,00, dentro do limite.', 6);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-6', 'a', 'Some apenas a renda do responsável financeiro.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-6', 'b', 'Some a renda bruta e divida pelo número de pessoas.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-6', 'c', 'Divida a renda líquida pelo salário mínimo.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-6', 'd', 'Considere somente a renda do estudante.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('eleg-7', 'elegibilidade', NULL, 'A renda usada no cálculo é a bruta ou a líquida?', 'É utilizada a renda familiar bruta, ou seja, a soma de todos os rendimentos apresentados pelo grupo familiar, sem descontos.', 7);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-7', 'a', 'A renda líquida após descontos.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-7', 'b', 'Apenas o salário registrado em carteira.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-7', 'c', 'A renda familiar bruta, sem descontos.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-7', 'd', 'Somente rendimentos de trabalho formal.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('eleg-8', 'elegibilidade', NULL, 'Sou professor(a) da educação básica. Que documento comprova isso?', 'É preciso apresentar o comprovante de efetivo exercício do magistério na educação básica, integrando o quadro de pessoal permanente de instituição pública. O documento deve ser solicitado nas secretarias municipais de educação e/ou coordenadorias regionais, e precisa conter a relação das matrículas e/ou contratos em seu nome, com a respectiva carga horária, impresso em papel timbrado, com carimbo e assinatura do(a) responsável.', 8);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-8', 'a', 'Comprovante de exercício do magistério na rede pública.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-8', 'b', 'Apenas declaração do próprio professor.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-8', 'c', 'Somente o diploma de graduação.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('eleg-8', 'd', 'Comprovante de matrícula em licenciatura.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('insc-1', 'como-se-inscrever', NULL, 'Onde e como faço a inscrição do PROUNI?', 'A inscrição é feita em etapa única e gratuita, exclusivamente pelo site oficial do PROUNI, usando o login único gov.br. Durante o período de inscrição é possível alterar as opções escolhidas quantas vezes quiser. Só vale a última inscrição confirmada. Não existe inscrição por e-mail, WhatsApp ou presencialmente na faculdade.', 1);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('insc-1', 'a', 'Presencialmente na Feevale, com taxa.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('insc-1', 'b', 'Por e-mail, sem login gov.br.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('insc-1', 'c', 'No site oficial do PROUNI, com login gov.br.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('insc-1', 'd', 'Em qualquer site de inscrição educacional.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('insc-2', 'como-se-inscrever', NULL, 'Quantas opções de curso posso escolher?', 'É possível selecionar até duas opções de curso e instituição durante o mesmo processo seletivo, podendo priorizar qual delas é a preferida.', 2);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('insc-2', 'a', 'Uma opção de curso.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('insc-2', 'b', 'Até duas opções de curso e instituição.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('insc-2', 'c', 'Até cinco opções em instituições diferentes.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('insc-2', 'd', 'Quantas opções desejar.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('insc-3', 'como-se-inscrever', NULL, 'Preciso pagar alguma taxa para me inscrever?', 'Não. A inscrição no PROUNI é totalmente gratuita. Qualquer cobrança para ''garantir'' a inscrição ou a bolsa é indício de golpe.', 3);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('insc-3', 'a', 'Não. A inscrição é totalmente gratuita.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('insc-3', 'b', 'Sim, há taxa obrigatória de inscrição.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('insc-3', 'c', 'Somente a segunda opção tem taxa.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('insc-3', 'd', 'A Feevale cobra uma taxa de garantia.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('insc-4', 'como-se-inscrever', NULL, 'Como sei se fui pré-selecionado?', 'O resultado da pré-seleção é divulgado no próprio site do PROUNI, na área do candidato, em data definida no cronograma oficial do processo seletivo daquele semestre.', 4);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('insc-4', 'a', 'Por telefone, antes do resultado.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('insc-4', 'b', 'Somente pela secretaria da instituição.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('insc-4', 'c', 'Pelo resultado do ENEM.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('insc-4', 'd', 'No site do PROUNI, na área do candidato.', true);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('doc-1', 'documentacao', NULL, 'Quais documentos comprovam a renda familiar?', 'Para cada integrante do grupo familiar com 16 anos ou mais, é obrigatória a cópia completa da Carteira de Trabalho Digital ou o CNIS, emitido pelo Meu INSS. Também é exigida a declaração completa do Imposto de Renda Pessoa Física com o recibo de entrega do último exercício (ou o print de isenção, se for o caso). Além disso, cada pessoa deve comprovar sua renda conforme a própria situação: contracheques para assalariados, declaração de autônomo para informais, comprovante de benefício para aposentados, DECORE para sócios de empresa, entre outros.', 1);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-1', 'a', 'Somente o comprovante de residência.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-1', 'b', 'Carteira de Trabalho ou CNIS, IR e comprovantes de renda.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-1', 'c', 'Apenas uma declaração assinada pelo estudante.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-1', 'd', 'Somente os três últimos extratos bancários.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('doc-2', 'documentacao', NULL, 'Como comprovo que estudei em escola pública?', 'É preciso apresentar o certificado e o histórico escolar completo do ensino médio, emitido pela escola, mostrando as instituições onde cada série foi cursada.', 2);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-2', 'a', 'Certificado e histórico escolar completo do ensino médio, emitidos pela escola.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-2', 'b', 'Declaração verbal do candidato.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-2', 'c', 'Somente o boletim do ENEM.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-2', 'd', 'Certidão de nascimento.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('doc-3', 'documentacao', NULL, 'Preciso de documento de identidade?', 'Sim, é exigido documento oficial com foto (RG ou CNH. A certidão de nascimento é aceita apenas se o(a) candidato(a) for menor de 18 anos e não tiver nenhum dos dois) e CPF, além dos documentos de renda e escolaridade. Também é exigido comprovante de residência atualizado de todos os membros do grupo familiar com mais de 18 anos. Não basta apresentar apenas um comprovante em nome do candidato ou do responsável pela casa.', 3);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-3', 'a', 'Somente o CPF do candidato.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-3', 'b', 'Apenas o documento do responsável pela casa.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-3', 'c', 'Documento com foto, CPF, renda e residência.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-3', 'd', 'Somente a certidão de nascimento.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('doc-4', 'documentacao', NULL, 'E se eu não tiver algum documento pedido?', 'Cada instituição publica sua própria lista de documentos aceitos como comprovação alternativa. Vale a pena consultar o edital da faculdade escolhida antes da data da comprovação presencial.', 4);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-4', 'a', 'Desistir automaticamente da inscrição.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-4', 'b', 'Enviar qualquer documento no lugar.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-4', 'c', 'Aguardar uma nova edição do PROUNI.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-4', 'd', 'Consultar a lista de documentos alternativos da instituição.', true);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('doc-5', 'documentacao', NULL, 'Existe alguma regra especial para quem tem até 24 anos?', 'Sim. Se você tiver 24 anos ou menos, é obrigatório apresentar os documentos de identificação, carteira de trabalho/CNIS e comprovação de renda de todo o seu grupo familiar de origem (pais ou responsáveis, irmãos e demais dependentes), mesmo que não more com eles. Caso se declare independente, é necessário comprovar renda própria condizente com seu padrão de vida e consumo, sob pena de reprovação, além de apresentar uma declaração explicando o motivo de não residir com os pais.', 5);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-5', 'a', 'Apresentar somente seus próprios documentos.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-5', 'b', 'Comprovar também a situação do grupo familiar de origem.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-5', 'c', 'Não apresentar documentos de renda.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-5', 'd', 'Apresentar apenas uma declaração de independência.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('doc-6', 'documentacao', NULL, 'Como funciona a política de cotas do PROUNI?', 'Para concorrer como cotista é preciso apresentar documento que comprove a etnia (certidão, autodeclaração reconhecida em cartório ou assinada eletronicamente pelo GOV.BR) ou, no caso de pessoa com deficiência, laudo médico atestando a espécie e o grau da deficiência com o código CID correspondente.', 6);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-6', 'a', 'Comprovar etnia ou deficiência conforme a modalidade.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-6', 'b', 'Basta declarar a renda familiar.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-6', 'c', 'Somente apresentar o histórico escolar.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-6', 'd', 'A cota é definida sem documentação.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('doc-7', 'documentacao', NULL, 'Preciso apresentar alguma certidão do INSS?', 'Sim, é obrigatória a Certidão Negativa ou Positiva de Benefícios do INSS de todos os integrantes do grupo familiar a partir de 18 anos, gerada pelo Meu INSS (acesse com sua conta gov.br, vá em ''Outros Serviços'' > ''Meus Benefícios'' e baixe o documento). Se ocorrer algum erro na emissão, é preciso contatar diretamente o INSS.', 7);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-7', 'a', 'A certidão só é exigida de aposentados.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-7', 'b', 'O documento é opcional.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-7', 'c', 'É exigida a Certidão Negativa ou Positiva de Benefícios do INSS dos integrantes do grupo familiar a partir de 18 anos.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-7', 'd', 'A certidão deve ser emitida pela Feevale.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('doc-8', 'documentacao', NULL, 'Como comprovo a situação da minha moradia?', 'Depende da situação: se a moradia for própria ou financiada, apresente a folha do IPTU do ano vigente com o Valor Venal Total ou a Base de Cálculo (constando nome do proprietário e endereço); em zona rural, apresente o ITR. Se for alugada, apresente o contrato de locação registrado em cartório e os três últimos recibos de pagamento. Se for cedida, além do IPTU, é exigida a Declaração de Casa Cedida assinada pelo cedente e o comprovante de endereço dele. Para outras situações (ocupação irregular, comodato, usufruto, etc.), use a Declaração de Situação de Moradia disponível em www.feevale.br/prouni.', 8);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-8', 'a', 'Apresentar somente uma conta de luz.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-8', 'b', 'O IPTU serve para qualquer tipo de moradia.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-8', 'c', 'Não é preciso comprovar a moradia.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-8', 'd', 'Os documentos dependem da situação do imóvel.', true);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('doc-9', 'documentacao', NULL, 'Sou sócio(a) ou diretor(a) de empresa. Quais documentos de renda preciso apresentar?', 'Se a empresa for enquadrada como Simples, Limitada ou Microempresa, é obrigatória a DECORE (Declaração Comprobatória de Percepção de Rendimentos) dos últimos três meses, assinada por contador(a) inscrito(a) no CRC, além da declaração completa do Imposto de Renda Pessoa Jurídica do último exercício, do Contrato Social (obrigatório) e alterações, se houver, e do extrato bancário dos últimos três meses da conta em que a renda é movimentada. Atenção: DECORE e Pró-Labore são documentos diferentes, e o Pró-Labore sozinho não é aceito. Se for MEI, os documentos mudam. Veja a próxima dúvida.', 9);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-9', 'a', 'DECORE, IRPJ, contrato social e extratos, conforme o caso.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-9', 'b', 'Somente o pró-labore.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-9', 'c', 'Apenas o contrato social.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-9', 'd', 'Somente uma declaração verbal.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('doc-10', 'documentacao', NULL, 'Sou MEI. Quais documentos preciso apresentar?', 'É preciso apresentar o Comprovante de MEI (emitido no site do governo, na área de serviços para MEI), uma declaração de renda informando o tipo de atividade e o valor médio mensal (modelo disponível em www.feevale.br/prouni), a declaração exigida pela Feevale para esse item, no caso do MEI, a DASN-SIMEI (Declaração Anual do Simples Nacional para o MEI), e o extrato bancário dos últimos três meses da conta em que a renda é movimentada.', 10);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-10', 'a', 'Apenas o cartão do CNPJ.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-10', 'b', 'Somente os extratos bancários.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-10', 'c', 'Comprovante de MEI, declaração de renda, DASN-SIMEI e extratos.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-10', 'd', 'Somente a declaração anual do IRPF.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('doc-11', 'documentacao', NULL, 'Como devem ser assinadas as declarações exigidas no processo?', 'Todas as declarações emitidas pelo(a) candidato(a) devem ser entregues em via original. A assinatura do(a) declarante precisa ser reconhecida em cartório (sendo aceito o reconhecimento por semelhança) ou feita eletronicamente pelo GOV.BR. Se o modelo de declaração pedir testemunhas, como na declaração de separação não legalizada, elas só precisam assinar o documento, sem necessidade de cartório, mas não podem ser membros do grupo familiar.', 11);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-11', 'a', 'Toda declaração pode ser apenas digitalizada.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-11', 'b', 'A assinatura deve ser reconhecida ou feita pelo GOV.BR.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-11', 'c', 'Testemunhas sempre precisam ir ao cartório.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-11', 'd', 'A assinatura do candidato é dispensável.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('doc-12', 'documentacao', NULL, 'Preciso comprovar algo sobre pensão alimentícia?', 'Sim, se algum integrante do grupo familiar recebe ou paga pensão alimentícia. Havendo decisão judicial, apresente a decisão e os seis últimos comprovantes de recebimento ou pagamento. Não havendo decisão judicial, apresente uma declaração informando o valor pago ou recebido (modelo disponível em www.feevale.br/prouni). Se houver direito à pensão mas ela não estiver sendo paga, também é preciso declarar o não recebimento.', 12);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-12', 'a', 'Pensão nunca precisa ser comprovada.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-12', 'b', 'Basta informar o valor verbalmente.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-12', 'c', 'Somente a decisão judicial é necessária.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-12', 'd', 'Apresente decisão e comprovantes, ou declaração quando não houver decisão.', true);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('doc-13', 'documentacao', NULL, 'Preciso apresentar certidão de casamento ou de óbito dos meus pais?', 'Sim, quando aplicável: certidão de casamento ou escritura pública de união estável, se os pais forem casados ou vivem em união estável; e certidão de óbito, em caso de pai ou mãe falecido(a). Se os pais forem separados sem união oficializada, é preciso apresentar a declaração de separação não legalizada, assinada por um dos cônjuges com duas testemunhas (que não podem ser do grupo familiar).', 13);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-13', 'a', 'Apresente certidão conforme a situação familiar.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-13', 'b', 'Certidão de casamento é sempre dispensável.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-13', 'c', 'Somente o estudante pode emitir a certidão.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-13', 'd', 'Certidão de óbito substitui todos os documentos.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('doc-14', 'documentacao', NULL, 'Se eu já tiver matrícula em faculdade pública, preciso fazer algo antes de entregar os documentos?', 'Sim. Como o PROUNI não permite vínculo simultâneo com instituição pública e gratuita, é obrigatório apresentar o documento oficial de cancelamento de matrícula e desistência de vaga antes da comprovação. Do mesmo modo, se você já for bolsista PROUNI ativo em outra instituição (ou nesta mesma), é preciso apresentar o Termo de Concessão da Bolsa atual, já que a aprovação neste processo encerra automaticamente a bolsa anterior.', 14);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-14', 'a', 'A matrícula pública pode ser mantida.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-14', 'b', 'Apenas a bolsa anterior precisa ser informada.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-14', 'c', 'É preciso cancelar o vínculo público antes da comprovação.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-14', 'd', 'Não é necessário apresentar nenhum documento.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('doc-15', 'documentacao', NULL, 'Sou isento(a) da declaração de Imposto de Renda. O que apresento no lugar?', 'Apresente o print da informação gerada pelo site oficial de consulta à restituição do Imposto de Renda (restituicao.receita.fazenda.gov.br), mostrando que não há declaração para o exercício informado.', 15);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-15', 'a', 'Entregue uma declaração escrita à mão.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-15', 'b', 'Apresente o comprovante oficial de isenção da Receita.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-15', 'c', 'Substitua por um comprovante de residência.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('doc-15', 'd', 'O documento não precisa ser substituído.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('prazo-1', 'prazos', NULL, 'Quando ocorrem as inscrições do PROUNI?', 'O PROUNI tem dois processos seletivos por ano, um por semestre. As inscrições do primeiro semestre costumam ocorrer entre os meses de fevereiro e março, e as do segundo semestre, entre junho e julho. As datas exatas mudam a cada edição e são publicadas no site oficial do PROUNI.', 1);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-1', 'a', 'Duas vezes por ano, com datas divulgadas no site oficial.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-1', 'b', 'Somente uma vez a cada dois anos.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-1', 'c', 'Todo mês, em datas fixas.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-1', 'd', 'Apenas quando a Feevale abrir vagas.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('prazo-2', 'prazos', NULL, 'Quanto tempo tenho para comprovar as informações?', 'Após a pré-seleção, existe um prazo definido no edital daquele semestre (geralmente cerca de dez dias) para comparecer à instituição de ensino e comprovar presencialmente os dados informados na inscrição.', 2);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-2', 'a', 'Até o fim do curso.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-2', 'b', 'Não há prazo definido.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-2', 'c', 'O prazo indicado no edital, geralmente cerca de dez dias.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-2', 'd', 'Somente após o início das aulas.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('prazo-3', 'prazos', NULL, 'O que acontece se eu perder o prazo de comprovação?', 'Perder o prazo de comprovação documental normalmente cancela a pré-seleção, e a vaga é repassada para o próximo candidato da lista de espera.', 3);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-3', 'a', 'A pré-seleção é mantida sem documentos.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-3', 'b', 'A pré-seleção normalmente é cancelada.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-3', 'c', 'O prazo é transferido para o semestre seguinte.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-3', 'd', 'A vaga fica reservada indefinidamente.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('prazo-4', 'prazos', NULL, 'Existe lista de espera no PROUNI?', 'Sim. Quem não é chamado na primeira ou na segunda chamada pode manifestar interesse na lista de espera, que segue convocando candidatos conforme vagas restantes no semestre.', 4);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-4', 'a', 'Não, só existem duas chamadas.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-4', 'b', 'Sim, mas apenas para quem já tem bolsa.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-4', 'c', 'Somente a Feevale pode criar lista de espera.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-4', 'd', 'Sim, ela convoca candidatos conforme surgem vagas.', true);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('prazo-5', 'prazos', NULL, 'Quais são as etapas do processo seletivo do PROUNI?', 'O processo seletivo ocorre nos dois semestres do ano e é composto por três etapas: primeira chamada, segunda chamada e lista de espera. Quem não for pré-selecionado nas duas chamadas pode manifestar interesse na lista de espera, que segue convocando candidatos conforme vagas restantes no semestre.', 5);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-5', 'a', 'Primeira chamada, segunda chamada e lista de espera.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-5', 'b', 'Inscrição, matrícula e formatura.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-5', 'c', 'Somente uma chamada e entrevista.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-5', 'd', 'Prova, entrevista e estágio.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('prazo-6', 'prazos', NULL, 'O que acontece depois que meus documentos são aprovados?', 'Após a instituição aprovar a comprovação das informações, o candidato assina o Termo de Concessão de Bolsa e realiza a matrícula. É responsabilidade do próprio candidato verificar, junto à instituição, os horários e o local de comparecimento para a comprovação. Perder o prazo ou não comprovar as informações resulta automaticamente na reprovação do candidato.', 6);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-6', 'a', 'A bolsa é liberada automaticamente sem matrícula.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-6', 'b', 'O candidato deve aguardar contato indefinidamente.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-6', 'c', 'Assine o termo e faça a matrícula após a aprovação.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-6', 'd', 'Basta enviar os documentos novamente.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('prazo-7', 'prazos', NULL, 'De quem é a responsabilidade por cumprir os prazos do PROUNI?', 'Todos os prazos referentes aos procedimentos acadêmicos e à bolsa do PROUNI, como inscrição, comprovação de documentos e renovação, são de responsabilidade exclusiva do(a) estudante bolsista. Perder um prazo, inclusive o de renovação da bolsa, pode acarretar a suspensão automática do benefício.', 7);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-7', 'a', 'A instituição é responsável por todos os prazos.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-7', 'b', 'O estudante bolsista deve acompanhar e cumprir os prazos.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-7', 'c', 'Somente o MEC acompanha os prazos.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('prazo-7', 'd', 'Os prazos deixam de valer após a aprovação.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('renov-1', 'renovacao-de-bolsa', NULL, 'A bolsa do PROUNI precisa ser renovada todo semestre?', 'Sim, a bolsa deve ser atualizada semestralmente. Na Feevale, a assinatura do Termo de Atualização ocorre nos meses de abril e outubro, conforme o cronograma do MEC, e depende do desempenho acadêmico e da frequência nas disciplinas.', 1);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('renov-1', 'a', 'A renovação ocorre somente ao final do curso.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('renov-1', 'b', 'A bolsa não precisa ser atualizada.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('renov-1', 'c', 'A renovação depende apenas da renda.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('renov-1', 'd', 'A bolsa é atualizada semestralmente.', true);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('renov-2', 'renovacao-de-bolsa', NULL, 'Qual desempenho acadêmico é exigido para não perder a bolsa?', 'É exigida aprovação em, no mínimo, 75% das disciplinas cursadas em cada período letivo (por exemplo, quem cursa 4 disciplinas precisa ser aprovado em pelo menos 3). Em caso de rendimento insuficiente, a coordenação do PROUNI pode autorizar a continuidade da bolsa por até duas vezes, mediante justificativa do(a) estudante.', 2);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('renov-2', 'a', 'É preciso aprovação em pelo menos 75% das disciplinas.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('renov-2', 'b', 'Basta ser aprovado em uma disciplina.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('renov-2', 'c', 'A frequência não interfere na bolsa.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('renov-2', 'd', 'Não existe desempenho mínimo.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('renov-3', 'renovacao-de-bolsa', NULL, 'Posso trancar a matrícula sem perder a bolsa?', 'Na Feevale, é possível trancar a matrícula e depois solicitar reingresso em até dois períodos letivos consecutivos (1 ano), desde que o curso não esteja em extinção; no curso de Medicina, esse prazo é de apenas 1 período (6 meses). Ultrapassado o prazo, a bolsa PROUNI é encerrada por evasão.', 3);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('renov-3', 'a', 'O trancamento sempre encerra a bolsa.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('renov-3', 'b', 'O prazo é ilimitado.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('renov-3', 'c', 'É possível trancar dentro do prazo permitido.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('renov-3', 'd', 'O prazo é igual para todos os cursos.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('renov-4', 'renovacao-de-bolsa', NULL, 'Preciso comprovar a renda de novo durante o curso?', 'Sim, a instituição pode realizar reavaliação socioeconômica periódica, e uma mudança substancial na condição socioeconômica do(a) estudante pode levar ao encerramento da bolsa.', 4);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('renov-4', 'a', 'A renda nunca é reavaliada.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('renov-4', 'b', 'A instituição pode realizar reavaliação socioeconômica.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('renov-4', 'c', 'Somente o MEC pode reavaliar a renda.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('renov-4', 'd', 'A reavaliação ocorre apenas após a formatura.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('renov-5', 'renovacao-de-bolsa', NULL, 'Se eu for reprovado(a) em uma disciplina, preciso pagar para cursá-la de novo?', 'Não. Como a Feevale oferece apenas bolsa integral, a instituição não pode cobrar do(a) bolsista pelas disciplinas (que estão na grade curricular do curso) cursadas novamente em caso de reprovação (dependências).', 5);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('renov-5', 'a', 'Não, a bolsa integral cobre a disciplina novamente.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('renov-5', 'b', 'Sim, sempre há cobrança integral.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('renov-5', 'c', 'A cobrança depende do número de reprovações.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('renov-5', 'd', 'Somente bolsistas parciais têm esse direito.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('perda-1', 'perda-da-bolsa', NULL, 'Quais situações levam ao encerramento da bolsa PROUNI?', 'Entre outros motivos, a bolsa pode ser encerrada por: não realizar a matrícula no primeiro semestre de usufruto; reprovação abaixo do mínimo exigido de disciplinas; mudança substancial na renda familiar; matrícula em instituição pública gratuita; conclusão do curso (ou de qualquer outro curso superior); término do prazo máximo de validade da bolsa; documentação ou informação falsa; não apresentar documentação pendente do processo de ingresso (por exemplo, ter concluído o ensino médio mas ainda não ter o certificado); acúmulo de mais de uma bolsa PROUNI; uso simultâneo com financiamento do FIES em curso ou instituição diferente; decisão ou ordem judicial; evasão; ou solicitação do próprio bolsista.', 1);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-1', 'a', 'A bolsa só termina por pedido do estudante.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-1', 'b', 'Somente a mudança de curso encerra a bolsa.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-1', 'c', 'Fatores como reprovação, fraude, evasão ou vínculo público podem encerrá-la.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-1', 'd', 'A bolsa nunca pode ser encerrada.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('perda-2', 'perda-da-bolsa', NULL, 'Quantas reprovações posso ter até perder a bolsa?', 'É preciso ser aprovado em, no mínimo, 75% das disciplinas cursadas em cada período letivo. Por exemplo: em 4 disciplinas, é necessário passar em ao menos 3; em 8 disciplinas, em ao menos 6. Ficar abaixo desse percentual pode levar ao encerramento da bolsa, embora a coordenação do PROUNI possa autorizar a continuidade por até duas vezes, mediante justificativa.', 2);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-2', 'a', 'É permitido reprovar em todas as disciplinas.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-2', 'b', 'É preciso aprovação mínima em 75% das disciplinas.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-2', 'c', 'Uma reprovação encerra sempre a bolsa.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-2', 'd', 'O desempenho não é analisado.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('perda-3', 'perda-da-bolsa', NULL, 'Se minha renda familiar aumentar, posso perder a bolsa?', 'Sim. A instituição pode realizar reavaliação socioeconômica periódica, e uma mudança substancial na condição socioeconômica do(a) estudante, como um aumento de renda que ultrapasse o limite exigido, pode levar ao encerramento da bolsa.', 3);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-3', 'a', 'A renda nunca interfere depois da aprovação.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-3', 'b', 'A bolsa vira parcial automaticamente.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-3', 'c', 'Apenas a renda do estudante é considerada.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-3', 'd', 'Uma mudança substancial pode encerrar a bolsa.', true);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('perda-4', 'perda-da-bolsa', NULL, 'Existe um prazo máximo para usar a bolsa PROUNI?', 'Sim. A bolsa pode ser utilizada durante um período equivalente a duas vezes o prazo normal de integralização do curso, descontados os semestres já cursados antes da concessão da bolsa. Ao concluir o curso, a bolsa é encerrada e os semestres restantes não podem ser aproveitados em outro curso ou especialização.', 4);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-4', 'a', 'Até duas vezes o prazo normal de integralização do curso.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-4', 'b', 'Somente até o primeiro semestre.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-4', 'c', 'Não existe prazo máximo.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-4', 'd', 'Até a conclusão de qualquer curso futuro.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('perda-5', 'perda-da-bolsa', NULL, 'Posso perder a bolsa se deixar a matrícula trancada por muito tempo?', 'Sim. Na Feevale, o reingresso após trancamento só é permitido em até dois períodos letivos consecutivos (1 ano); no curso de Medicina, o limite é de 1 período (6 meses). Ultrapassado esse prazo, a bolsa é encerrada por evasão.', 5);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-5', 'a', 'O trancamento pode durar indefinidamente.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-5', 'b', 'O prazo é sempre de dois anos.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-5', 'c', 'O reingresso deve ocorrer dentro do prazo permitido.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-5', 'd', 'O prazo não depende do curso.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('perda-6', 'perda-da-bolsa', NULL, 'O que acontece se eu me matricular em uma faculdade pública?', 'A bolsa é encerrada. Não é permitida a concessão nem a manutenção de bolsa PROUNI para quem está matriculado, a qualquer tempo, em instituição de ensino superior pública e gratuita.', 6);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-6', 'a', 'A bolsa continua normalmente.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-6', 'b', 'A bolsa é encerrada.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-6', 'c', 'A bolsa fica automaticamente parcial.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-6', 'd', 'A bolsa é transferida para a instituição pública.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('perda-7', 'perda-da-bolsa', NULL, 'O que acontece se eu apresentar informações ou documentos falsos?', 'A prestação de informações falsas ou a apresentação de documentação inidônea, mesmo identificada após a matrícula, leva ao encerramento da bolsa (assegurados contraditório e ampla defesa ao estudante), sem prejuízo de sanções penais e civis cabíveis.', 7);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-7', 'a', 'O documento falso é corrigido sem consequência.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-7', 'b', 'A bolsa fica garantida após a matrícula.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-7', 'c', 'Apenas uma multa é aplicada.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-7', 'd', 'A bolsa pode ser encerrada, com direito à defesa.', true);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('perda-8', 'perda-da-bolsa', NULL, 'Posso ter duas bolsas PROUNI ao mesmo tempo?', 'Não. Só é permitido manter uma bolsa PROUNI por vez. Se o bolsista se inscrever novamente em um processo seletivo e for aprovado, a bolsa anterior é encerrada automaticamente.', 8);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-8', 'a', 'Não. É permitido manter apenas uma bolsa por vez.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-8', 'b', 'Sim, sem qualquer limite.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-8', 'c', 'Sim, desde que sejam cursos diferentes.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-8', 'd', 'Somente duas bolsas integrais são permitidas.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('perda-9', 'perda-da-bolsa', NULL, 'Posso usar bolsa PROUNI e financiamento FIES ao mesmo tempo?', 'Não. É proibido usufruir, ao mesmo tempo, de bolsa PROUNI e financiamento do FIES em curso ou instituição diferentes. Isso leva ao encerramento da bolsa PROUNI. Se você já tinha um contrato de financiamento do FIES antes de receber a bolsa integral do PROUNI, deve solicitar o encerramento desse contrato diretamente com o agente financeiro (banco).', 9);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-9', 'a', 'O PROUNI e o FIES sempre podem ser acumulados.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-9', 'b', 'A regra vale apenas para bolsas parciais.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-9', 'c', 'Não é permitido usar bolsa PROUNI e FIES nas situações vedadas.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-9', 'd', 'O FIES cancela apenas a matrícula.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('perda-10', 'perda-da-bolsa', NULL, 'Perder a bolsa é a mesma coisa que ficar com ela suspensa?', 'Não. A suspensão é temporária, por exemplo, durante um trancamento de matrícula dentro do prazo permitido ou por falta de atualização do usufruto pelo coordenador. O período suspenso é descontado do prazo total de uso da bolsa, sem que o estudante perca a bolsa ou fique devendo nesse período. Já o encerramento é definitivo.', 10);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-10', 'a', 'Suspensão e encerramento são a mesma coisa.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-10', 'b', 'Suspensão é temporária; encerramento é definitivo.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-10', 'c', 'O encerramento pode ser revertido automaticamente.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-10', 'd', 'A suspensão elimina todos os semestres usados.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('perda-11', 'perda-da-bolsa', NULL, 'O que acontece se a bolsa for concedida depois que as aulas já começaram?', 'Se a matrícula do(a) bolsista ocorrer em período incompatível com o calendário letivo, impossibilitando a frequência e podendo gerar reprovação por faltas, a instituição deve emitir o Termo de Concessão de Bolsa e suspender seu usufruto até o período letivo seguinte, sem prejuízo ao(à) estudante. Este semestre suspenso contará no prazo total para finalizar o curso.', 11);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-11', 'a', 'A matrícula é cancelada imediatamente.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-11', 'b', 'O estudante perde o direito ao benefício.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-11', 'c', 'A bolsa passa a ser cobrada retroativamente.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('perda-11', 'd', 'O usufruto pode ser suspenso até o período seguinte.', true);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('dir-1', 'direitos-e-beneficios', NULL, 'Preciso devolver o dinheiro da bolsa depois de formado(a)?', 'Não. A bolsa é um benefício concedido pelo Governo Federal e não está condicionada a nenhuma forma de restituição monetária. Ao concluir o curso, o(a) bolsista não fica devendo nada aos cofres públicos.', 1);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-1', 'a', 'Não. A bolsa não precisa ser devolvida após a formatura.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-1', 'b', 'Sim, todo o valor deve ser pago.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-1', 'c', 'A devolução depende da renda final.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-1', 'd', 'Apenas metade do valor é devolvida.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('dir-2', 'direitos-e-beneficios', NULL, 'Já iniciei outra faculdade antes. Posso aproveitar as disciplinas já cursadas?', 'Sim, é possível solicitar aproveitamento curricular das disciplinas já cursadas, mas isso fica sujeito à análise do departamento responsável na instituição para a qual o(a) estudante foi selecionado(a).', 2);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-2', 'a', 'O aproveitamento é automático.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-2', 'b', 'Nenhuma disciplina pode ser aproveitada.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-2', 'c', 'É possível solicitar análise de aproveitamento curricular.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-2', 'd', 'Apenas disciplinas do mesmo semestre são aceitas.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('dir-3', 'direitos-e-beneficios', NULL, 'Posso ter bolsa PROUNI e bolsa de iniciação científica ao mesmo tempo?', 'Sim, não existe impedimento legal para o bolsista do PROUNI se candidatar também a uma bolsa de iniciação científica.', 3);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-3', 'a', 'As duas bolsas são proibidas juntas.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-3', 'b', 'A iniciação científica cancela o PROUNI.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-3', 'c', 'Somente bolsistas parciais podem acumular benefícios.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-3', 'd', 'É possível ter PROUNI e bolsa de iniciação científica.', true);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('dir-4', 'direitos-e-beneficios', NULL, 'Sou bolsista PROUNI e estou grávida. Tenho algum direito especial?', 'Sim, a estudante gestante tem direito a até 90 dias de ausência justificada às aulas (Lei nº 6.202/1975). No entanto, continua obrigatória a realização de provas, a apresentação de trabalhos em datas especiais e a realização da matrícula.', 4);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-4', 'a', 'Pode ter até 90 dias de ausência justificada.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-4', 'b', 'Não possui nenhum direito adicional.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-4', 'c', 'Pode faltar sem realizar avaliações.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-4', 'd', 'A gravidez encerra a bolsa.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('dir-5', 'direitos-e-beneficios', NULL, 'O que é a Bolsa Permanência?', 'É um benefício extra em dinheiro, com valor equivalente ao das bolsas federais de iniciação científica, pago mensalmente a bolsistas com bolsa integral do PROUNI em cursos presenciais de no mínimo 6 semestres de duração e carga horária média de pelo menos 6 horas diárias de aula.', 5);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-5', 'a', 'É um desconto na mensalidade.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-5', 'b', 'É uma bolsa exclusiva para professores.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-5', 'c', 'É um benefício mensal em dinheiro para alguns bolsistas integrais.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-5', 'd', 'É um empréstimo estudantil.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('dir-6', 'direitos-e-beneficios', NULL, 'Como faço para receber a Bolsa Permanência?', 'É preciso abrir uma conta corrente individual no Banco do Brasil ou na Caixa Econômica Federal (não pode ser poupança, conta eletrônica ou com mais de um titular) e depois ir à Coordenação do PROUNI da instituição, levando documento de identidade, CPF, comprovante bancário e comprovante de residência, para assinar o Termo de Concessão. Assim que liberado no sistema, o NAE entra em contato com o aluno (na Feevale apenas os alunos de Medicina recebem a Bolsa Permanência) solicitando as informações bancárias para cadastro no Sisprouni e solicitamos a assinatura eletrônica do termo.', 6);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-6', 'a', 'Abra uma conta poupança conjunta.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-6', 'b', 'Abra conta corrente individual e assine o termo na instituição.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-6', 'c', 'Receba automaticamente sem apresentar documentos.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-6', 'd', 'Solicite o pagamento diretamente ao banco sem a instituição.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('dir-7', 'direitos-e-beneficios', NULL, 'Perco a Bolsa Permanência se minha bolsa PROUNI for suspensa?', 'Sim, o pagamento da Bolsa Permanência é interrompido enquanto a bolsa PROUNI estiver suspensa, voltando a ser pago quando a bolsa PROUNI voltar a ser utilizada.', 7);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-7', 'a', 'O pagamento continua sem alterações.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-7', 'b', 'O benefício vira uma dívida.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-7', 'c', 'A Bolsa Permanência é encerrada definitivamente.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-7', 'd', 'O pagamento é interrompido durante a suspensão e pode retornar depois.', true);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('dir-8', 'direitos-e-beneficios', NULL, 'Se a Feevale sair do programa PROUNI, eu perco minha bolsa?', 'Não. Ao aderir ao PROUNI, a instituição assume o compromisso de manter a bolsa dos estudantes já matriculados, mesmo que decida deixar o programa antes do fim do prazo de adesão.', 8);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-8', 'a', 'Não. A Feevale deve manter a bolsa dos estudantes já matriculados.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-8', 'b', 'Sim, a bolsa termina imediatamente.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-8', 'c', 'A bolsa vira financiamento.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-8', 'd', 'O estudante deve mudar de instituição.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('dir-9', 'direitos-e-beneficios', NULL, 'Existem bolsas fora do processo seletivo regular?', 'Sim, são as chamadas bolsas remanescentes: vagas não preenchidas no processo seletivo, que podem ser oferecidas a estudantes já matriculados na instituição e que atendam aos critérios socioeconômicos do PROUNI, em prazo estabelecido pelo MEC. Diferente da bolsa regular, a bolsa remanescente não tem efeito retroativo. Sua vigência começa a partir da data de emissão do Termo de Concessão, então o(a) estudante não tem direito ao ressarcimento de parcelas já pagas naquele semestre antes de ser contemplado. Porém, no momento a Feevale não possui bolsas remanescentes disponíveis.', 9);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-9', 'a', 'São bolsas oferecidas somente a formados.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-9', 'b', 'São bolsas sem critérios socioeconômicos.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-9', 'c', 'São vagas não preenchidas que podem ser oferecidas a estudantes elegíveis.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-9', 'd', 'São bolsas com efeito retroativo garantido.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('dir-10', 'direitos-e-beneficios', NULL, 'Como funciona a seleção para a Bolsa Permanência?', 'A seleção dos estudantes aptos é feita mensalmente, de forma automática, pelo sistema do PROUNI. O pagamento, porém, depende da disponibilidade orçamentária e financeira do Ministério da Educação, além da assinatura do Termo de Concessão pelo bolsista e do envio mensal da relação de beneficiários pela coordenação do PROUNI da instituição.', 10);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-10', 'a', 'A seleção é feita manualmente pelo estudante.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-10', 'b', 'A seleção é automática e mensal, mas depende de recursos e procedimentos.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-10', 'c', 'O pagamento é sempre garantido pelo MEC.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-10', 'd', 'A seleção ocorre somente uma vez por ano.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('dir-11', 'direitos-e-beneficios', NULL, 'Em quais casos a Bolsa Permanência é encerrada definitivamente (não só suspensa)?', 'A Bolsa Permanência é encerrada quando: o curso deixa de atender ao critério de carga horária média de pelo menos 6 horas diárias; a bolsa PROUNI do(a) estudante é encerrada; o(a) estudante é transferido(a) para um curso que não se enquadra nos critérios do benefício; é constatado que o valor não está sendo usado para despesas educacionais; há inidoneidade de documento ou informação falsa; ou por solicitação do(a) próprio(a) estudante.', 11);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-11', 'a', 'A bolsa nunca pode ser encerrada.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-11', 'b', 'Somente a mudança de endereço encerra o benefício.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-11', 'c', 'O benefício termina apenas após a formatura.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('dir-11', 'd', 'Pode terminar por perda dos critérios, encerramento da bolsa ou informação falsa.', true);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('feevale-1', 'procedimentos-e-contato-na-feevale', NULL, 'Como funciona a entrega de documentos na Feevale?', 'Para pré-selecionados em primeira ou segunda chamada, e para quem está na lista de espera dentro da classificação de vagas, é preciso agendar horário, dentro do prazo disponibilizado pelo MEC, para entrevista pelo telefone (51) 3586-8800, ramal 6545, com atendimento na sala 300L, prédio Lilás, Campus II. Quem manifestou interesse na lista de espera mas está fora da classificação de vagas entrega os documentos em envelope lacrado, sem agendamento, de segunda a sexta-feira, das 8h30 às 12h e das 13h às 20h, no mesmo local.', 1);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-1', 'a', 'Pré-selecionados em chamada e classificados na lista de espera devem seguir as orientações de agendamento ou entrega de documentos da Feevale.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-1', 'b', 'Todos entregam documentos sem agendamento.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-1', 'c', 'A entrega ocorre somente por e-mail.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-1', 'd', 'A documentação é enviada diretamente ao MEC.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('feevale-2', 'procedimentos-e-contato-na-feevale', NULL, 'Posso transferir minha bolsa PROUNI para a Feevale ou trocar de curso mantendo a bolsa?', 'No momento, a Feevale não possui previsão de oferta de vagas PROUNI para transferências internas ou externas. Há exceções previstas em lei a essa regra. Veja a próxima dúvida.', 2);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-2', 'a', 'A Feevale oferece transferências PROUNI regularmente.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-2', 'b', 'Toda transferência é automática.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-2', 'c', 'Atualmente não há previsão de vagas para transferências.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-2', 'd', 'A transferência depende somente do estudante.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('feevale-3', 'procedimentos-e-contato-na-feevale', NULL, 'Como peço o comprovante de que sou bolsista PROUNI?', 'A solicitação do Comprovante de Condição de Bolsista deve ser feita pelo e-mail prouni@feevale.br.', 3);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-3', 'a', 'Solicite o comprovante na secretaria do curso.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-3', 'b', 'Solicite pelo e-mail prouni@feevale.br.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-3', 'c', 'O comprovante é enviado automaticamente.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-3', 'd', 'Solicite diretamente ao MEC.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('feevale-4', 'procedimentos-e-contato-na-feevale', NULL, 'Preciso avisar a Feevale se eu mudar de curso ou tiver alguma alteração na matrícula?', 'Sim. É responsabilidade do(a) bolsista comunicar ao Núcleo de Apoio ao Estudante (NAE) qualquer alteração em sua matrícula, para garantir a continuidade do benefício, além de manter os dados de contato sempre atualizados no sistema da instituição. No momento não há previsão para liberação de troca de curso para aluno PROUNI na instituição. Mas qualquer alteração ou solicitação, o aluno PROUNI deve procurar o NAE antes de qualquer coisa.', 4);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-4', 'a', 'Alterações de matrícula não precisam ser comunicadas.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-4', 'b', 'Somente mudanças de endereço precisam ser informadas.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-4', 'c', 'O estudante deve aguardar o fim do semestre.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-4', 'd', 'Comunique alterações ao NAE e mantenha os contatos atualizados.', true);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('feevale-5', 'procedimentos-e-contato-na-feevale', NULL, 'Quem pode assinar o Termo de Atualização da Bolsa?', 'Somente o próprio bolsista ou seu representante legal pode assinar o Termo de Atualização (ou o Termo de Suspensão, caso a bolsa esteja suspensa). A assinatura é obrigatória para a renovação da bolsa.', 5);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-5', 'a', 'O próprio bolsista ou seu representante legal.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-5', 'b', 'Qualquer colega de turma.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-5', 'c', 'Somente o professor responsável.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-5', 'd', 'Somente o MEC.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('feevale-6', 'procedimentos-e-contato-na-feevale', NULL, 'Onde entro em contato para tirar dúvidas sobre o PROUNI na Feevale?', 'Pelo Núcleo de Apoio ao Estudante (NAE): e-mail prouni@feevale.br, telefone (51) 3586-8800 ramal 6545, sala 300L, 3º andar, prédio Lilás, Campus II. Para dúvidas gerais sobre o programa PROUNI, também é possível ligar na Central de Atendimento do MEC: 0800 616161.', 6);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-6', 'a', 'Somente pela central do MEC.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-6', 'b', 'Apenas presencialmente no campus.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-6', 'c', 'Pelo NAE, usando os canais de contato da Feevale.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-6', 'd', 'Exclusivamente pelo portal do estudante.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('feevale-7', 'procedimentos-e-contato-na-feevale', NULL, 'Como peço reingresso depois de trancar a matrícula?', 'É preciso preencher o formulário de reingresso disponibilizado pela Feevale, dentro do prazo estipulado pela instituição e apresentar toda a documentação para comprovação da situação socioeconômica. A solicitação é analisada pela Comissão do PROUNI, que dá o retorno por e-mail, e o deferimento fica condicionado à existência de vaga acadêmica. Ao reingressar, o(a) estudante fica sujeito ao currículo e às normas institucionais vigentes na data da matrícula.', 7);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-7', 'a', 'O reingresso é automático após o trancamento.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-7', 'b', 'Preencha o formulário da Feevale dentro do prazo.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-7', 'c', 'Basta voltar a frequentar as aulas.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-7', 'd', 'Solicite o reingresso diretamente ao MEC.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('feevale-8', 'procedimentos-e-contato-na-feevale', NULL, 'Existe alguma exceção à regra de não haver vagas para transferência?', 'Não existe esta exceção na Feevale. A questão de transferência é uma definição institucional de cada universidade. A Universidade Feevale não aceita, neste momento, a transferência ou troca de curso.', 8);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-8', 'a', 'Não. A Feevale não libera exceções para transferência ou troca de curso.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-8', 'b', 'A instituição pode cobrar taxa para analisar a transferência.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-8', 'c', 'Somente mudança de cidade permite transferência.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-8', 'd', 'A lei garante a transferência para qualquer curso da Feevale.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('feevale-9', 'procedimentos-e-contato-na-feevale', NULL, 'Que restrições nacionais existem para uma transferência de bolsa ser aceita?', 'Além da disponibilidade de vaga no curso de destino, a transferência só é permitida se a nota do ENEM usada pelo(a) bolsista para entrar no PROUNI for igual ou superior à do último candidato aprovado no processo seletivo mais recente para o curso de destino, e se o total de semestres já cursados ou suspensos não for igual ou superior à duração do curso de destino.', 9);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-9', 'a', 'A nota do ENEM e o tempo cursado devem atender aos critérios nacionais.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-9', 'b', 'Apenas a disponibilidade de vaga importa.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-9', 'c', 'A transferência independe da nota do ENEM.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-9', 'd', 'O curso de destino pode ter duração menor sem restrição.', false);
INSERT INTO perguntas (pergunta_id, categoria_id, pergunta_base_id, enunciado, resposta, ordem) VALUES ('feevale-10', 'procedimentos-e-contato-na-feevale', NULL, 'Sou menor de idade. Preciso levar alguém comigo na entrevista?', 'Sim. Se o(a) candidato(a) tiver menos de 18 anos, é obrigatório comparecer à entrevista de comprovação acompanhado de um responsável legal.', 10);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-10', 'a', 'Não, menores podem ir sozinhos.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-10', 'b', 'Somente um colega precisa acompanhar.', false);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-10', 'c', 'Sim, é obrigatório comparecer com um responsável.', true);
INSERT INTO alternativas (pergunta_id, letra, texto, correta) VALUES ('feevale-10', 'd', 'A presença de responsável só é exigida após a matrícula.', false);
